def iter_words():
    for level in sorted(BANK):
        for sequence, row in enumerate(BANK[level], start=1):
            text, part, pronunciation, meaning, tip, example = row
            yield {
                "text": text,
                "part_of_speech": part,
                "pronunciation": pronunciation,
                "meaning": meaning,
                "tip": tip,
                "example": example,
                "level": level,
                "sequence": sequence,
            }


def bank_signature():
    payload = json.dumps(list(iter_words()), sort_keys=True, ensure_ascii=True)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()
